import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"8. 联盟领地","description":"","frontmatter":{},"headers":[],"relativePath":"union-claims.md","filePath":"union-claims.md"}'),l={name:"union-claims.md"};function i(d,t,p,o,r,c){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="_8-联盟领地" tabindex="-1">8. 联盟领地 <a class="header-anchor" href="#_8-联盟领地" aria-label="Permalink to &quot;8. 联盟领地&quot;">​</a></h1><p>联盟领地是<strong>联盟共有的领地</strong>，用 <code>/gclaim</code> 管理，和个人的 <code>/pclaim</code> 是两套独立系统：额度、金库、权限都算联盟的，不属于任何个人。</p><ul><li>只能加入联盟后才能创建和使用联盟领地（见 <a href="/union.html">7. 联盟</a>）。</li><li>创建与管理需要<strong>盟主或对应职位权限</strong>；普通成员主要是在领地内建造、使用容器和传送。</li><li>联盟领地和你的个人领地<strong>不能重叠</strong>。</li></ul><h2 id="_8-1-基本规则" tabindex="-1">8.1 基本规则 <a class="header-anchor" href="#_8-1-基本规则" aria-label="Permalink to &quot;8.1 基本规则&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>规则</th></tr></thead><tbody><tr><td>初始额度</td><td>1,024 格（联盟等级 Lv.1）</td></tr><tr><td>每级增加</td><td>+512 格（当前等级固定 Lv.1，实际不增长）</td></tr><tr><td>额度上限</td><td>4,096 格</td></tr><tr><td>购买价格</td><td><strong>当前实际 100 钻石/格</strong>（标价 1，见 <a href="/economy.html#_5-4-赚钱与花钱">5.4 赚钱与花钱</a>），从联盟金库扣</td></tr><tr><td>领地数量</td><td>不限（只受总面积限制）</td></tr><tr><td>最小边长</td><td>3 格</td></tr><tr><td>最大边长</td><td>128 格</td></tr><tr><td>最大长宽比</td><td>8:1</td></tr><tr><td>子领地</td><td>每块主领地最多 10 块，仅一层</td></tr><tr><td>子领地边长</td><td>3–64 格</td></tr><tr><td>与其他联盟领地间距</td><td>至少 8 格</td></tr><tr><td>主城</td><td>主城全境不可圈地（服务器保护区）</td></tr><tr><td>出生点</td><td>每个世界的出生点 100 格内不能完整圈地</td></tr></tbody></table><blockquote><p>单边 128 是硬上限，但面积上限 4,096 会先触发。实际形状通常不超过 64×64 的正方形，只有狭长形状才可能用到 128 边。</p></blockquote><h2 id="_8-2-创建联盟领地" tabindex="-1">8.2 创建联盟领地 <a class="header-anchor" href="#_8-2-创建联盟领地" aria-label="Permalink to &quot;8.2 创建联盟领地&quot;">​</a></h2><p>先用金锄圈出范围（与个人领地相同的操作），再：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gclaim create &lt;名字&gt;</span></span></code></pre></div><ul><li>需要盟主或拥有相应职位的成员执行。</li><li>名字规则与个人领地相同：2 字符以上，只能用字母、数字、下划线。</li><li>与个人领地、其他联盟领地都不能重叠；和别人的联盟领地之间至少要留 8 格。</li></ul><h2 id="_8-3-额度与扩容" tabindex="-1">8.3 额度与扩容 <a class="header-anchor" href="#_8-3-额度与扩容" aria-label="Permalink to &quot;8.3 额度与扩容&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gclaim quota               查看联盟当前额度</span></span>
<span class="line"><span>/gclaim buy &lt;格数&gt;          用联盟金库购买额度</span></span>
<span class="line"><span>/gclaim expand &lt;格数&gt; [方向]  扩边</span></span>
<span class="line"><span>/gclaim resize &lt;领地&gt;        重新圈选后应用新范围</span></span></code></pre></div><ul><li>免费额度 1,024 格，买满上限是 4,096 格。</li><li>购买额度从<strong>联盟金库</strong>扣款，当前实际价格 <strong>100 钻石/格</strong>——标价是 1 钻石/格，实际扣费是它的 100 倍，属于待修正的价格问题（见 <a href="/economy.html#_5-4-赚钱与花钱">5.4</a>）。在管理组调整前，不建议通过界面大批购买。</li><li>扩容和重划共用 72 小时冷却；缩小领地会按规则返还额度。</li></ul><h2 id="_8-4-保护与权限" tabindex="-1">8.4 保护与权限 <a class="header-anchor" href="#_8-4-保护与权限" aria-label="Permalink to &quot;8.4 保护与权限&quot;">​</a></h2><p>联盟领地的保护和旗标系统与个人领地相同，但权限按<strong>联盟职位</strong>分配：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gclaim flag &lt;领地&gt; &lt;旗标&gt; &lt;值&gt;          设置领地旗标</span></span>
<span class="line"><span>/gclaim perms &lt;领地&gt;                     查看各职位的权限</span></span>
<span class="line"><span>/gclaim perm &lt;领地&gt; &lt;职位&gt; &lt;旗标&gt; &lt;值&gt;    设置某个职位的权限</span></span>
<span class="line"><span>/gclaim ban &lt;玩家&gt; [领地]                禁止某人进入/使用</span></span>
<span class="line"><span>/gclaim unban &lt;玩家&gt; [领地]              解除封禁</span></span></code></pre></div><ul><li>默认成员在联盟领地内可以建造和使用容器。如果不想让所有成员都能动，用 <code>/gclaim perm</code> 调整职位权限。</li><li>管理组层面：盟主的管理权限高于普通成员，具体职位可以在 <code>/union rank</code> 里自建并分配。</li><li>领地保护只针对没有权限的人；同联盟有权限的成员可以正常建造。</li></ul><h2 id="_8-5-传送与子领地" tabindex="-1">8.5 传送与子领地 <a class="header-anchor" href="#_8-5-传送与子领地" aria-label="Permalink to &quot;8.5 传送与子领地&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gclaim settp              设置联盟领地传送点</span></span>
<span class="line"><span>/gclaim tp                 传送到联盟领地</span></span>
<span class="line"><span>/gclaim sub create &lt;名字&gt;   创建子领地</span></span>
<span class="line"><span>/gclaim map                打开联盟领地地图</span></span>
<span class="line"><span>/gclaim borders            显示联盟领地边界</span></span></code></pre></div><ul><li>传送点、传送冷却规则与个人领地一致。</li><li>子领地只能有一层（子领地下面不能再套子领地），每块主领地上限 10 块，边长 3–64 格。</li></ul><h2 id="_8-6-删除联盟领地" tabindex="-1">8.6 删除联盟领地 <a class="header-anchor" href="#_8-6-删除联盟领地" aria-label="Permalink to &quot;8.6 删除联盟领地&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/gclaim delete &lt;领地&gt;</span></span></code></pre></div><p>需要在 10 秒内执行 <code>/gclaim confirm</code> 确认。</p><p>删除<strong>只解除保护，不动领地里的方块</strong>：建筑、箱子、红石设施都原样留在原地。消失的是领地本身——范围、旗标、职位权限、传送点都会一起没掉，且无法恢复；买额度花掉的钻石也不退，但这段面积会释放回联盟的额度池。</p><p>真打算放弃这块地，记得先把值钱的东西搬走——删掉之后那片区域对所有人都是野外。</p>`,25)])])}const u=a(l,[["render",i]]);export{g as __pageData,u as default};
